/**
 * Pages modelled on the real test world (docs/PLAN-v2.md section 2 and the phase 0 spike): ids, names and shapes as
 * LegendKeeper returns them. They are written by hand (generated by code where a page is long), not copied from the
 * world, so nothing private is committed.
 */
import type { LkBlock, LkRun } from '../../src/markdown/types.js';

const t = (text: string, marks: Record<string, unknown> = {}): LkRun => ({ text, ...marks });
const para = (id: string, ...content: LkRun[]): LkBlock => ({ id, kind: 'paragraph', content });
const heading = (id: string, level: number, text: string): LkBlock => ({
  id,
  kind: 'heading',
  level,
  content: [t(text)],
});

