/** The date forms the age tables use (PLAN-v2 section 1), with the KCY rule for the Fourth Age (year + 1,250,307). */
const MONTHS = [
  'Kumikas',
  'Isar',
  'Selaphos',
  'Azah',
  'Selyros',
  'Sarias',
  'Highsun',
  'Surion',
  'Azaakh',
  'Malakh',
  'Zahras',
];
const ord = (d: number) =>
  `${d}${d % 10 === 1 && d !== 11 ? 'st' : d % 10 === 2 && d !== 12 ? 'nd' : d % 10 === 3 && d !== 13 ? 'rd' : 'th'}`;
function dateCell(i: number): { date: string; kcy: string } {
  const year = 1 + Math.floor(i / 3);
  const k = year + 1_250_307;
  switch (i % 7) {
    case 0:
      return {
        date: `${year === 1 ? 'Azah 18th' : `${MONTHS[i % MONTHS.length]} ${ord((i % 34) + 1)}`}, 4A ${year}`,
        kcy: String(k),
      };
    case 1:
      return { date: `4A ${year}`, kcy: String(k) };
    case 2:
      return { date: `Kumikas 19th, 4A ${year} - Meshaph 10th, 4A ${year + 2}`, kcy: `${k}-${k + 2}` };
    case 3:
      return { date: `Kumikas - Azaakh, 4A ${year}`, kcy: String(k) };
    case 4:
      return { date: `Unknown, 4A ${year}`, kcy: String(k) };
    case 5:
      return { date: `4A ${year} - 4A ${year + 19}`, kcy: `${k}-${k + 19}` };
    default:
      return { date: `${MONTHS[(i * 3) % MONTHS.length]} ${ord((i % 30) + 1)}, 4A ${year}`, kcy: String(k) };
  }
}

const EVENTS = [
  'The Sundering of the Northern Reaches',
  'Founding of Sarias by the River Kings',
  'The Long Winter',
  'Rise of the Hollow King',
  'Fall of Ashgate',
  'Treaty of Reeds',
  'Burning of the Great Library of Kusha',
  'Birth of Asagiri Miyabi',
  'Coronation of Queen Selyra II',
  'The Quiet Years',
];

/**
 * The Fourth Arkonan Age table page: a heading, two paragraphs, a three-column plain-text table (Historical Event |
 * Date | KCY) with `rows` rows, then more headings and paragraphs. 430 rows make about 3,000 blocks and about 200,000
 * characters of JSON, the size of the real page (about 235,000).
 */
export function fourthAgeTablePage(rows = 430): LkBlock[] {
  const cell = (id: string, content: LkRun[], header = false): LkBlock => ({
    id: `c${id}`,
    kind: 'tableCell',
    ...(header ? { header: true } : {}),
    children: [{ id: `q${id}`, kind: 'paragraph', content }],
  });
  const body: LkBlock[] = [];
  for (let i = 0; i < rows; i++) {
    const { date, kcy } = dateCell(i);
    const name = `${EVENTS[i % EVENTS.length]}${i >= EVENTS.length ? ` (${Math.floor(i / EVENTS.length) + 1})` : ''}`;
    const event: LkRun[] =
      i % 50 === 7
        ? [{ mention: { resourceId: 'bsrc0001', text: name } }, t(' (disputed)', { italic: true })]
        : [t(name)];
    body.push({
      id: `r${String(i).padStart(7, '0')}`,
      kind: 'tableRow',
      children: [
        cell(`${i}a`.padStart(8, '0'), event),
        cell(`${i}b`.padStart(8, '0'), [t(date)]),
        cell(`${i}c`.padStart(8, '0'), [t(kcy)]),
      ],
    });
  }
  return [
    heading('h4age001', 1, 'Fourth Arkonan Age - Table'),
    para(
      'p4age001',
      t(
        'Every dated event of the Fourth Arkonan Age, in calendar order. Year-only events follow the dated events of their year.',
      ),
    ),
    para('p4age002', t('KCY is the continuous year count: for the Fourth Age, KCY = year + 1,250,307.')),
    {
      id: 't4age001',
      kind: 'table',
      children: [
        {
          id: 'r4head01',
          kind: 'tableRow',
          children: [
            cell('hd00000a', [t('Historical Event')], true),
            cell('hd00000b', [t('Date')], true),
            cell('hd00000c', [t('KCY')], true),
          ],
        },
        ...body,
      ],
    },
    heading('h4age002', 2, 'Sources'),
    para('p4age003', t('Compiled from the temple archives of Kusha and the River Kings’ annals.')),
    heading('h4age003', 2, 'Notes'),
    para(
      'p4age004',
      t('Dates marked '),
      t('(disputed)', { italic: true }),
      t(' are contested between the two archives.'),
    ),
  ];
}

/** The Universal Chronology's Main page: an index table whose cells mention each age's table and timeline documents. */
export function mainChronologyPage(): LkBlock[] {
  const ages: [string, string, string, string][] = [
    ['First Arkonan Age', '12', 'doc1tbl1', 'doc1tml1'],
    ['Second Arkonan Age', '87', 'doc2tbl1', 'doc2tml1'],
    ['Third Arkonan Age', '311', 'doc3tbl1', 'doc3tml1'],
    ['Fourth Arkonan Age', '1,204', 'bt0bm3pc', 'g2lm1d0v'],
  ];
  const cell = (id: string, content: LkRun[], header = false): LkBlock => ({
    id: `mc${id}`,
    kind: 'tableCell',
    ...(header ? { header: true } : {}),
    children: [{ id: `mp${id}`, kind: 'paragraph', content }],
  });
  return [
    heading('mainh001', 1, 'Universal Chronology'),
    para(
      'mainp001',
      t('The index of the ages. Each age has a dated table (the authority) and an interactive timeline.'),
    ),
    {
      id: 'maint001',
      kind: 'table',
      children: [
        {
          id: 'mainr000',
          kind: 'tableRow',
          children: ['Age', 'Event count', 'Complete dated table', 'Interactive timeline'].map((h, i) =>
            cell(`h${i}`, [t(h)], true),
          ),
        },
        ...ages.map(([age, count, table, timeline], i) => ({
          id: `mainr00${i + 1}`,
          kind: 'tableRow',
          children: [
            cell(`${i}a`, [t(age)]),
            cell(`${i}b`, [t(count)]),
            cell(`${i}c`, [
              { mention: { resourceId: 'h0gczxh7', documentId: table, text: `${age} - Table` } },
            ]),
            cell(`${i}d`, [
              { mention: { resourceId: 'h0gczxh7', documentId: timeline, text: `${age} - Timeline` } },
            ]),
          ],
        })),
      ],
    },
  ];
}

